INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-ai-compress-enabled', 'ai-engine', 'ecos.ai.session.compress.enabled', 'true', 'boolean', '会话压缩开关', 'Session Compression Switch', 'false = 跳过压缩但必须上报 compressSkipped=true（F06-09 要点 1，禁静默关闭）；长期关闭会使上下文逼近模型上限并由 CONTEXT_OVERFLOW(413) 兜底', '2', 'active', '2026-11-10 06:54:08.183223', '2026-11-10 06:54:08.183223', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-ai-compress-enabled');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-ai-compress-keep-recent', 'ai-engine', 'ecos.ai.session.compress.keep_recent', '6', 'number', '压缩保留窗口', 'Compression Keep Recent', '最近 K 轮原文保留（F06-09 要点 2，默认 6）；更早轮交 llm-gateway 生成结构化摘要（confirmedFacts/userPreferences/openQuestions/keyRefs），摘要失败退化为截断最早轮并记 compression_mode=TRUNCATE_FALLBACK 供抽检', '4', 'active', '2026-11-10 06:54:08.183223', '2026-11-10 06:54:08.183223', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-ai-compress-keep-recent');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-ai-compress-threshold', 'ai-engine', 'ecos.ai.session.compress.threshold', '0.6', 'number', '压缩触发阈值', 'Compression Threshold', '触发比例：estimatedContextTokens > modelLimit × 本值 时压缩（F06-09 要点 1，替代旧"20 条"计数口径）。modelLimit 取自 llm-gateway 模型目录，禁引擎内硬编码（联动 X-71 配置单源）', '3', 'active', '2026-11-10 06:54:08.183223', '2026-11-10 06:54:08.183223', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-ai-compress-threshold');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-ai-session-token-limit', 'ai-engine', 'ecos.ai.session.token_limit', '200000', 'number', '会话 token 上限', 'Session Token Limit', '会话累计 token 用量上限（输入+输出，真值来自 llm-gateway 唯一计量点）。达到即终止 Agent Loop 并回可读消息 + 诊断码 ECOS-AI-413，禁继续静默消耗（F06-07 要点 3）。0 或未配置 = 不启用配额；读数失败时同样不判定但必记 ERROR（成本控制项，禁静默降级）', '1', 'active', '2026-11-10 06:54:08.183223', '2026-11-10 06:54:08.183223', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-ai-session-token-limit');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-audit-retention', 'security', 'audit_retention_days', '180', 'INTEGER', '审计日志保留天数', NULL, '审计日志保留天数', '0', 'active', '2026-11-10 06:56:54.855091', '2026-11-10 06:56:54.855091', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-audit-retention');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-cache-default-ttl', 'cache', 'ecos.cache.default_ttl_seconds', '120', 'int', '缓存·缺省 TTL（秒）', 'Cache Default TTL (sec)', '写入未显式给 TTL 时的缺省值；≤0 视为不缓存。最终 TTL 仍受 max_stale_seconds 钳制，故本值大于上限时以硬上限为准', '2', 'active', '2026-11-10 06:55:02.709583', '2026-11-10 06:55:02.709583', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-cache-default-ttl');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-cache-enabled', 'cache', 'ecos.cache.enabled', 'false', 'bool', '缓存·总开关', 'Cache Enabled', '受控加速层总开关（§2.9.8①）。false ⇒ get 恒空、put 恒 no-op，调用方一律回源（绝不把「没有缓存」当「没有数据/没有权限」）。默认关闭；翻 true 前须确认三项已达标：陈旧上限为正值、写路径已接失效、缓存命中不绕鉴权', '1', 'active', '2026-11-10 06:55:02.696539', '2026-11-10 06:55:02.696539', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-cache-enabled');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-cache-max-stale', 'cache', 'ecos.cache.max_stale_seconds', '60', 'int', '缓存·最大陈旧时间（秒）', 'Cache Max Stale (sec)', '所有写入的 TTL 天花板（显式 TTL 也压不过）。权限类对象（角色·权限·授权关系）在本值 ≤0 时一律拒缓存——「撤权最迟多久可见」无法证明就不启用缓存（§2.9.8⑥ fail-closed）。撤权本身由写路径提交后即时失效，本值只是 Cache-Aside 竞态的兜底窗口', '3', 'active', '2026-11-10 06:55:02.71717', '2026-11-10 06:55:02.71717', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-cache-max-stale');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-cache-redis-enabled', 'cache', 'ecos.cache.redis_enabled', 'false', 'bool', '缓存·Redis 通道', 'Cache Redis Enabled', 'Redis 通道开关。当前基线为 false（Redis 未接入运行链路，存储为进程内 TTL）；接 Redis 须先补 runtime 底座远程实现并另行裁决容器，铁律「不新增 Docker container」在其前仍然有效。本开关为 true 但底座缺失时须显式降级，不得静默假装分布式', '4', 'active', '2026-11-10 06:55:02.726783', '2026-11-10 06:55:02.726783', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-cache-redis-enabled');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-cog-demo', 'cognitive', 'ecos.cognitive.demo', 'false', 'boolean', 'demo 内容开关', 'Demo Content Switch', '默认 false = 生产不可达：内置情景模板 /scenario/list 返 404；仅 dev profile 置 true 时可达且逐行 demo=true（F05-16 要点 5 / X-44）', '2', 'active', '2026-11-10 06:54:06.501644', '2026-11-10 06:54:06.501644', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-cog-demo');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-cog-domain-alias', 'cognitive', 'ecos.cognition.domain_alias', '经营=FORECAST;运营=DETECT', 'string', '领域名→能力别名表', 'Domain Capability Alias', 'belief.domain ↔ MindCapabilityMask 中文别名映射，形态 "domain=CAPABILITY" 以 ; 或换行分隔；新增别名只改本行不改代码（F05-11 要点 2）。未命中 ⇒ capability=null + issue 记录（DG-7，行不丢）', '4', 'active', '2026-11-10 06:54:06.501644', '2026-11-10 06:54:06.501644', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-cog-domain-alias');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-cog-engine-enabled', 'cognitive', 'ecos.cognitive.enabled', 'true', 'boolean', '认知引擎总开关', 'Cognitive Engine Switch', 'false 时 E1~E4 全部 503 ECOS-COG-500 "cognitive engine not enabled"（DG-1，用户裁定 A3 原样穿透，禁 200 空 body）', '1', 'active', '2026-11-10 06:54:06.501644', '2026-11-10 06:54:06.501644', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-cog-engine-enabled');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-cog-eval-trend-weight', 'cognitive', 'ecos.cognitive.eval.trend_weight', '1', 'number', 'E2 趋势权重', 'E2 Trend Weight', 'E2 算式 score = probability × trend_weight 的第二因子；本期恒 1（PRD-05 §1.1 规格 1 冻结，不实现动态学习）。空白/非数/负值 ⇒ 应用侧回落 1 并在响应 trendWeightSource 标注 DEFAULT', '3', 'active', '2026-11-10 06:54:06.501644', '2026-11-10 06:54:06.501644', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-cog-eval-trend-weight');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-fc-bt-mape-ratio', 'fc.backtest', 'ecos.fc.backtest.review_threshold.mape_ratio', '0.15', 'number', '回测·MAPE 越限线', 'Backtest MAPE Ceiling', 'PRD/R-66 原文 MAPE>15%。数值沿用既有确定性评估面（DeterministicErrorCalculator 产出）的聚合 MAPE，本组阈值只做比较、禁回测侧重算；zero-actual 行按 PRD §5.2 排除在比率之外。既有评估面没产出 MAPE ⇒ 该闸不评估并记 MAPE_GATE_UNEVALUABLE（禁代 0 或代 1）', '2', 'active', '2026-11-10 06:54:30.562136', '2026-11-10 06:54:30.562136', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-fc-bt-mape-ratio');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-fc-bt-min-data-cov', 'fc.backtest', 'ecos.fc.backtest.review_threshold.min_data_coverage', '0.80', 'number', '回测·数据覆盖率下限', 'Backtest Data Coverage Min', 'R-66 原文 覆盖率<80% 的数据面：该期 ACTUAL 格子数 / 应预测格子数（应预测数取库内评估行数，禁前端传）。ACTUAL=0 与 ACTUAL 未回灌是两种真态，前者计分子、后者计缺项并逐枚列 missingRefs（DG-6 空集与故障严格可分）', '4', 'active', '2026-11-10 06:54:30.562136', '2026-11-10 06:54:30.562136', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-fc-bt-min-data-cov');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-fc-bt-min-interval-cov', 'fc.backtest', 'ecos.fc.backtest.review_threshold.min_interval_coverage', '0.80', 'number', '回测·区间覆盖率下限', 'Backtest Interval Coverage Min', 'R-66 原文 覆盖率<80% 的区间面：实际 ∈ [P10,P90] 的格子数 / 可判格子数。分母只含三值齐备的样本；缺 P10/P90 或实际值的行进排除集并逐条记原因（禁由 P50 或邻值插值合成，R-62 ①）。无可判样本 ⇒ 该闸既不通过也不越限（两态严格可分）', '3', 'active', '2026-11-10 06:54:30.562136', '2026-11-10 06:54:30.562136', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-fc-bt-min-interval-cov');
INSERT INTO ecos_control.sys_config (id, config_group, config_key, config_value, config_type, config_label, config_label_en, description, sort_order, status, created_at, updated_at, edition) SELECT 'cfg-fc-bt-min-samples', 'fc.backtest', 'ecos.fc.backtest.review_threshold.min_samples', '5', 'number', '回测·最小样本量(LOW_SAMPLE)', 'Backtest Min Sample Count', 'PRD-09 §5.2 守卫原文 n<5 ⇒ LOW_SAMPLE，不参与告警。n 取"预测与实际双侧齐备"的实测有效样本数，不是请求声明的行数（拿应有行充样本会让守卫形同虚设）。未配置 / 空白 / 非整数 ⇒ 应用侧判 null 并 fail-closed 记 LOW_SAMPLE（禁截断猜值、禁代码缺省）', '1', 'active', '2026-11-10 06:54:30.562136', '2026-11-10 06:54:30.562136', 'all' WHERE NOT EXISTS (SELECT 1 FROM ecos_control.sys_config WHERE id = 'cfg-fc-bt-min-samples');
