-- 认知方法论框架注册表
-- ---------------------------------------------------------------------------

-- ============================================================================
-- 后置自检：登录关键表非空
-- ============================================================================
DO $$
DECLARE
    v_n BIGINT;
    v_msg TEXT := '';
BEGIN
    SELECT count(*) INTO v_n FROM ecos_control.td_user;
    IF v_n = 0 THEN RAISE EXCEPTION 'ecos_control.td_user 为空 ⇒ IAM 面失效'; END IF;
    v_msg := v_msg || 'td_user=' || v_n;
    -- 登录可用性：NOLOGIN: 前缀是刻意不可登录的哨兵（12 行演示账号），不能算可登录面
    SELECT count(*) INTO v_n FROM ecos_control.td_user
     WHERE status = 'ACTIVE' AND password IS NOT NULL AND password NOT LIKE 'NOLOGIN:%';
    IF v_n = 0 THEN RAISE EXCEPTION 'td_user 无 ACTIVE 且非 NOLOGIN 哨兵的账号 ⇒ 新库无法登录'; END IF;
    v_msg := v_msg || ' loginable=' || v_n;
    -- 超管码必须在位：rbac.rego 取首角色，PermissionAspect 大小写敏感比 ROLE_SUPER_ADMIN/admin
    SELECT count(*) INTO v_n FROM ecos_control.td_user_role ur
      JOIN ecos_control.td_role r ON ur.role_id = r.role_id
      JOIN ecos_control.td_user u ON u.user_id = ur.user_id
     WHERE u.username = 'admin' AND r.role_code = 'ROLE_SUPER_ADMIN';
    IF v_n <> 1 THEN RAISE EXCEPTION 'admin 缺 ROLE_SUPER_ADMIN 隶属 ⇒ 超管授权面失效（期望 1 行，实得 %）', v_n; END IF;
    v_msg := v_msg || ' admin_super=' || v_n;
    SELECT count(*) INTO v_n FROM ecos_control.td_role_permission;
    IF v_n = 0 THEN RAISE EXCEPTION 'ecos_control.td_role_permission 为空 ⇒ 授权面失效'; END IF;
    v_msg := v_msg || ' td_role_permission=' || v_n;
    SELECT count(*) INTO v_n FROM ecos_control.sys_config;
    IF v_n = 0 THEN RAISE EXCEPTION 'ecos_control.sys_config 为空 ⇒ 配置面失效'; END IF;
    v_msg := v_msg || ' sys_config=' || v_n;
    RAISE NOTICE '10_system_seed 自检通过：%', v_msg;
END $$;

\if :{?ecos_commit}
    \if :ecos_commit
        COMMIT;
        \echo '10_system_seed 已提交（ecos_commit=1）'
    \else
        ROLLBACK;
        \echo '10_system_seed 已回滚（dry-run，未传 ecos_commit=1）'
    \endif
\else
    ROLLBACK;
    \echo '10_system_seed 已回滚（dry-run，未传 ecos_commit=1）'
\endif
